final class EventBus {
    private final Map<Class<?>, List<Handler<ParcelEvent>>> registry = new ConcurrentHashMap<>();
    private final Map<Class<?>, List<Class<?>>> keyCache = new ConcurrentHashMap<>();
    private final ErrorHandler onError;
    private final Next pipeline;

    EventBus(List<Middleware> middleware, ErrorHandler onError) {
        this.onError = onError;
        Next next = this::deliver;
        for (Middleware m : List.copyOf(middleware).reversed()) {   // reversed(): JDK 21
            Next rest = next;
            next = event -> m.intercept(event, rest);
        }
        this.pipeline = next;
    }

    <E extends ParcelEvent> AutoCloseable subscribe(Class<E> type, Handler<? super E> handler) {
        Handler<ParcelEvent> adapter = event -> handler.handle(type.cast(event));
        List<Handler<ParcelEvent>> handlers = registry.computeIfAbsent(type, t -> new CopyOnWriteArrayList<>());
        handlers.add(adapter);
        return () -> handlers.remove(adapter);
    }

    int publish(ParcelEvent event) { return pipeline.proceed(event); }

    private int deliver(ParcelEvent event) {
        int called = 0;
        for (Class<?> key : keyCache.computeIfAbsent(event.getClass(), EventBus::dispatchKeys)) {
            for (Handler<ParcelEvent> h : registry.getOrDefault(key, List.of())) {
                called++;
                try { h.handle(event); } catch (Exception e) { onError.onError(event, e); }
            }
        }
        return called;
    }

    private static List<Class<?>> dispatchKeys(Class<?> type) { /* breadth-first walk, as above */ }
}

